create index if not exists "idx_tickets_company_status" on "tickets" ("company_id", "status");
create index if not exists "idx_tickets_open_due" on "tickets" ("step_due_date") where "status" not in ('Completed', 'Rejected', 'Cancelled');
create index if not exists "idx_tickets_open_step" on "tickets" ("current_step_id") where "status" not in ('Completed', 'Rejected', 'Cancelled');
create index if not exists "idx_ticket_history_ticket_time" on "ticket_history" ("ticket_id", "timestamp");
create index if not exists "idx_user_role_assignments_user" on "user_role_assignments" ("user_id");
create index if not exists "idx_user_role_assignments_company_role" on "user_role_assignments" ("company_id", "role_id");
create index if not exists "idx_step_approvers_step" on "step_approvers" ("step_id");
create index if not exists "idx_step_approvers_role" on "step_approvers" ("role_id");
create index if not exists "idx_custom_field_values_entity" on "custom_field_values" ("ticket_id", "entity_category");
create index if not exists "idx_workflow_steps_type_company_order" on "workflow_steps" ("ticket_type_id", "company_id", "sort_order");
create index if not exists "idx_admin_action_logs_time" on "admin_action_logs" ("timestamp");
create index if not exists "idx_notifications_user_unread" on "notifications" ("user_id", "is_read", "created_at" desc);
create index if not exists "idx_tickets_company_type_created" on "tickets" ("company_id", "ticket_type_id", "created_at" desc, "id" desc);
create index if not exists "idx_tickets_requester_created" on "tickets" ("requester_id", "created_at" desc, "id" desc);
create index if not exists "idx_tickets_head_inbox" on "tickets" ("head_approver_id") where "current_step_id" = '__head__';
create index if not exists "idx_tickets_search" on "tickets" using gin ("search");
create index if not exists "idx_tickets_number_trgm" on "tickets" using gin ("ticket_number" gin_trgm_ops);
create index if not exists "idx_ticket_participants_user_ticket" on "ticket_participants" ("user_id", "ticket_id");
create index if not exists "idx_ticket_participants_pool" on "ticket_participants" ("role_id", "step_id") where "user_id" is null;
create index if not exists "idx_approval_delegations_delegate_window" on "approval_delegations" ("delegate_id", "start_date", "end_date") where "is_active";
create index if not exists "idx_notifications_role" on "notifications" ("recipient_role_id", "created_at" desc) where "recipient_role_id" is not null;
create index if not exists "idx_email_outbox_pending" on "email_outbox" ("status", "created_at") where "status" = 'pending';
create index if not exists "idx_ticket_comments_ticket_time" on "ticket_comments" ("ticket_id", "created_at");
create index if not exists "idx_ticket_action_logs_ticket_time" on "ticket_action_logs" ("ticket_id", "timestamp");
create index if not exists "idx_ticket_attachments_ticket_status" on "ticket_attachments" ("ticket_id", "upload_status");
create index if not exists "idx_ticket_attachments_cleanup" on "ticket_attachments" ("upload_status", "created_at");
create index if not exists "idx_ticket_links_parent" on "ticket_links" ("parent_ticket_id");
create index if not exists "idx_ticket_links_child" on "ticket_links" ("child_ticket_id");
create index if not exists "idx_ticket_tag_assignments_ticket" on "ticket_tag_assignments" ("ticket_id");
create index if not exists "idx_ticket_collaborations_ticket" on "ticket_collaborations" ("ticket_id");
create index if not exists "idx_ticket_collaborations_shared_with" on "ticket_collaborations" ("shared_with_user_id") where "is_active";
create index if not exists "idx_custom_fields_type_order" on "custom_fields" ("ticket_type_id", "entity_category", "sort_order");
create index if not exists "idx_dropdown_options_list" on "dropdown_options" ("dropdown_list_id");
create index if not exists "idx_step_conditions_step" on "step_conditions" ("step_id", "condition_group");
create index if not exists "idx_step_slas_step" on "step_slas" ("step_id");
create index if not exists "idx_sla_escalation_rules_scope" on "sla_escalation_rules" ("company_id", "ticket_type_id", "step_id", "level");
create index if not exists "idx_sla_escalation_events_ticket" on "sla_escalation_events" ("ticket_id");
create index if not exists "idx_company_holidays_company_date" on "company_holidays" ("company_id", "date");
create index if not exists "idx_country_holidays_country_date" on "country_holidays" ("country_code", "date");
create index if not exists "idx_company_subscriptions_company" on "company_subscriptions" ("company_id", "period_start" desc);
create index if not exists "idx_user_invites_email" on "user_invites" (lower("email")) where "is_active";
create index if not exists "idx_user_profiles_email" on "user_profiles" (lower("email"));
create index if not exists "idx_organization_members_user" on "organization_members" ("user_id") where "is_active";
create index if not exists "idx_companies_organization" on "companies" ("organization_id");
create index if not exists "idx_idempotency_keys_created" on "idempotency_keys" ("created_at");
